package com.m3u.extractor;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 int bg=0xff0b1220,panel=0xff172338,blue=0xff3478f6,muted=0xff9caec8; TextView[] values=new TextView[3]; TextView status; String[] data={"","",""}; ClipboardManager clip; LinearLayout root;
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable shape(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(16));return d;}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
 void add(LinearLayout p,View v,int margin){LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(-1,-2);l.bottomMargin=dp(margin);p.addView(v,l);}
 TextView button(String s,int c,Runnable r){TextView t=text(s,16,Color.WHITE);t.setGravity(Gravity.CENTER);t.setTypeface(null,Typeface.BOLD);t.setPadding(dp(12),dp(15),dp(12),dp(15));t.setBackground(shape(c));t.setOnClickListener(v->r.run());return t;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);clip=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(bg);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(24),dp(20),dp(24));scroll.addView(root);setContentView(scroll);
 TextView title=text("M3U Extractor",30,Color.WHITE);title.setTypeface(null,Typeface.BOLD);add(root,title,3);add(root,text("PRO  •  Extração inteligente",14,0xff79aaff),26);add(root,text("LINK M3U",12,muted),8);add(root,button("Toque aqui para colar o M3U",blue,()->paste()),10);status=text("O usuário será copiado automaticamente.",13,muted);add(root,status,22);
 String[] names={"Usuário","Senha","DNS"};for(int i=0;i<3;i++){final int n=i;LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(16),dp(14),dp(16),dp(14));card.setBackground(shape(panel));add(card,text(names[i].toUpperCase(),12,muted),8);values[i]=text("—",20,Color.WHITE);values[i].setTypeface(null,Typeface.BOLD);add(card,values[i],12);add(card,button("Copiar "+names[i].toLowerCase(),0xff254a82,()->copy(n)),0);add(root,card,12);}add(root,button("Limpar campos",panel,()->clear("Pronto para um novo link.")),12);add(root,text("OFFLINE  •  Sem anúncios  •  Sem envio de dados",12,muted),0);}
 void clear(String s){for(int i=0;i<3;i++){data[i]="";values[i].setText("—");}status.setText(s);}
 void paste(){try{ClipData c=clip.getPrimaryClip();if(c==null||c.getItemCount()==0)throw new Exception();String s=c.getItemAt(0).coerceToText(this).toString().trim();Uri u=Uri.parse(s);String a=u.getQueryParameter("username"),p=u.getQueryParameter("password");if(a==null||a.isEmpty()||p==null||p.isEmpty()||u.getHost()==null||!("http".equalsIgnoreCase(u.getScheme())||"https".equalsIgnoreCase(u.getScheme())))throw new Exception();data[0]=a;data[1]=p;data[2]=u.getScheme()+"://"+u.getEncodedAuthority();for(int i=0;i<3;i++)values[i].setText(data[i]);copy(0);status.setText("✓ Link extraído. Usuário copiado!");}catch(Exception e){clear("Copie um link M3U válido e toque novamente.");}}
 void copy(int i){if(data[i].isEmpty()){status.setText("Cole um link M3U primeiro.");return;}ClipData c=ClipData.newPlainText("M3U",data[i]);if(Build.VERSION.SDK_INT>=33){PersistableBundle extras=new PersistableBundle();extras.putBoolean("android.content.extra.IS_SENSITIVE",true);c.getDescription().setExtras(extras);}clip.setPrimaryClip(c);status.setText("✓ "+new String[]{"Usuário","Senha","DNS"}[i]+" copiado!");}
}